        t.appendChild(h("tr", null, h("th", null, `sequence ${r + 1}`), row.map((tok) => h("td", null, SPECIAL.has(tok) ? h("span", { class: "chip lm-spc" + (tok === "PAD" ? " pad" : "") }, h("span", { class: "chip-t" }, tok)) : chip(tok)))));
